const cron=require("node-cron"),cronController=require("../cronController.min.js"),systemController=require("../systemController.min.js");function scheduleDailyRankings(){cron.schedule("00 59 23 * * *",()=>{cronController.get_rankings("daily")})}function scheduleWeeklyRankings(){cron.schedule("10 59 23 * * 5",()=>{cronController.get_rankings("weekly")})}function scheduleMonthlyRankings(){cron.schedule("40 59 23 * * *",()=>{const n=new Date,e=new Date(n.getFullYear(),n.getMonth()+1,0).getDate();n.getDate()===e&&(cronController.get_rankings("monthly"),systemController.changeSystemInfo())})}function scheduleYearlyRankings(){cron.schedule("30 59 23 1 1 *",()=>{cronController.get_rankings("yearly")})}function initializeScheduledTasks(){scheduleDailyRankings(),scheduleWeeklyRankings(),scheduleMonthlyRankings(),scheduleYearlyRankings()}module.exports={initializeScheduledTasks}; 